(950, 'garden', '/ˈɡɑːrdən/', 'noun', '{"zh-TW":["花園"],"en":["a piece of land for growing plants"]}', NULL, 'rooftop garden / garden party', '[{"en":"The hotel has a beautiful rooftop garden.","zh-TW":"飯店有一個漂亮的屋頂花園。"},{"en":"They held a garden party for staff.","zh-TW":"他們為員工舉辦了花園派對。"}]', '{"noun":"garden","noun2":"gardener","noun3":"gardening","verb":"garden"}', NULL, 2, 950),
(951, 'gather', '/ˈɡæðər/', 'verb', '{"zh-TW":["收集；聚集"],"en":["to bring together; to collect information"]}', NULL, 'gather information/data', '[{"en":"We gathered data from multiple sources.","zh-TW":"我們從多個來源收集了數據。"},{"en":"The team gathered to discuss the issue.","zh-TW":"團隊聚集起來討論這個問題。"}]', '{"noun":"gathering","verb":"gather"}', NULL, 2, 951),
(952, 'gauge', '/ɡeɪdʒ/', 'verb / noun', '{"zh-TW":["衡量；測量器"],"en":["to estimate or measure; a measuring instrument"]}', NULL, 'gauge interest/response', '[{"en":"It''s difficult to gauge customer interest.","zh-TW":"很難衡量客戶興趣。"},{"en":"The survey gauged employee satisfaction.","zh-TW":"調查衡量了員工滿意度。"}]', '{"noun":"gauge","verb":"gauge"}', NULL, 2, 952),
(953, 'general', '/ˈdʒenərəl/', 'adjective', '{"zh-TW":["一般的；總體的"],"en":["affecting or including all; not specific"]}', NULL, 'in general / general manager', '[{"en":"In general, sales have been improving.","zh-TW":"一般來說，銷售一直在改善。"},{"en":"The general consensus is to proceed.","zh-TW":"普遍共識是繼續進行。"}]', '{"noun":"generalization","verb":"generalize","adjective":"general","adverb":"generally"}', NULL, 3, 953),
(954, 'generate', '/ˈdʒenəreɪt/', 'verb', '{"zh-TW":["產生；創造","產生；生成"],"en":["to produce or create"]}', '{"root":{"text":"gener","meaning":"birth/produce (生產)"},"suffix":{"text":"-ate","meaning":"make (使)"},"logic":"使其產生，即「生成」。"}', 'generate revenue/ideas; generate revenue / generate electricity / generate ideas', '[{"en":"The campaign generated significant revenue.","zh-TW":"該活動產生了可觀的收入。"},{"en":"Solar panels generate clean energy.","zh-TW":"太陽能板產生清潔能源。"},{"en":"The project will generate new jobs.","zh-TW":"這個專案將創造新的就業機會。"},{"en":"Solar panels generate electricity from sunlight.","zh-TW":"太陽能板從陽光產生電力。"}]', '{"noun":"generation/generator","verb":"generate","noun2":"generator"}', NULL, 3, 954),
(955, 'generous', '/ˈdʒenərəs/', 'adjective', '{"zh-TW":["慷慨的；豐厚的","慷慨的；大方的"],"en":["willing to give more than expected","willing to give more than is expected"]}', '{"root":{"text":"gener","meaning":"birth/kind (出身/種類)"},"suffix":{"text":"-ous","meaning":"full of (充滿)"},"logic":"出身高貴而樂於給予的，即「慷慨的」。"}', 'generous offer/donation; generous donation / generous offer', '[{"en":"The company offers generous benefits.","zh-TW":"公司提供豐厚的福利。"},{"en":"It was a generous donation.","zh-TW":"這是一筆慷慨的捐贈。"},{"en":"She is very generous with her time.","zh-TW":"她很慷慨地付出時間。"},{"en":"That was a generous donation.","zh-TW":"那是一筆慷慨的捐款。"}]', '{"noun":"generosity","adjective":"generous","adverb":"generously"}', NULL, 3, 955),
(956, 'genuine', '/ˈdʒenjuɪn/', 'adjective', '{"zh-TW":["真正的；真誠的"],"en":["truly what it is said to be; sincere","truly what something is said to be; authentic"]}', '{"root":{"text":"genu","meaning":"birth/native (天生)"},"suffix":{"text":"-ine","meaning":"relating to (相關的)"},"logic":"與天生本性相關的，即「真正的」。"}', 'genuine concern/interest; genuine interest / genuine concern / genuine article', '[{"en":"She showed genuine interest in the project.","zh-TW":"她對該項目表現出真誠的興趣。"},{"en":"Is this a genuine product?","zh-TW":"這是正品嗎？"},{"en":"She showed genuine interest in the topic.","zh-TW":"她對這個話題表現出真正的興趣。"},{"en":"Is this a genuine Picasso painting?","zh-TW":"這是真的畢卡索畫作嗎？"}]', '{"adjective":"genuine","adverb":"genuinely"}', NULL, 3, 956),
(957, 'gesture', '/ˈdʒestʃər/', 'noun', '{"zh-TW":["姿態；表示"],"en":["a movement or action to express an idea; a kind act"]}', NULL, 'a goodwill gesture', '[{"en":"The bonus was a gesture of appreciation.","zh-TW":"獎金是一種感謝的表示。"},{"en":"It was a kind gesture from the management.","zh-TW":"這是管理層善意的姿態。"}]', '{"noun":"gesture","verb":"gesture"}', NULL, 3, 957),
(958, 'gift', '/ɡɪft/', 'noun', '{"zh-TW":["禮物；天賦"],"en":["something given freely","a natural talent"]}', NULL, 'gift card / gift wrap', '[{"en":"We offer gift cards for loyal customers.","zh-TW":"我們為忠實客戶提供禮品卡。"},{"en":"She has a gift for communication.","zh-TW":"她有溝通的天賦。"}]', '{"noun":"gift","adjective":"gifted"}', NULL, 1, 958),
(959, 'glad', '/ɡlæd/', 'adjective', '{"zh-TW":["高興的"],"en":["feeling pleasure and happiness"]}', NULL, 'glad to help / glad to hear', '[{"en":"I am glad to help you with this.","zh-TW":"我很樂意幫你處理這件事。"},{"en":"I am glad to hear the good news.","zh-TW":"我很高興聽到好消息。"}]', '{"adjective":"glad","adverb":"gladly"}', NULL, 1, 959),
(960, 'glass', '/ɡlæs/', 'noun', '{"zh-TW":["玻璃；玻璃杯"],"en":["a hard transparent material","a container for drinking"]}', NULL, 'glass ceiling / glass of water', '[{"en":"Women still face the glass ceiling.","zh-TW":"女性仍面臨玻璃天花板效應。"},{"en":"Would you like a glass of water?","zh-TW":"你要一杯水嗎？"}]', '{"noun":"glass","adjective":"glassy"}', NULL, 2, 960),
(961, 'global', '/ˈɡloʊbəl/', 'adjective', '{"zh-TW":["全球的"],"en":["relating to the whole world"]}', NULL, 'global market/economy', '[{"en":"The company has a global presence.","zh-TW":"該公司在全球有業務。"},{"en":"Global trade continues to expand.","zh-TW":"全球貿易持續擴張。"}]', '{"noun":"globalization","adjective":"global","adverb":"globally"}', NULL, 2, 961),
(962, 'gold', '/ɡoʊld/', 'noun', '{"zh-TW":["黃金；金色"],"en":["a precious yellow metal","something very valuable"]}', NULL, 'gold standard / gold medal', '[{"en":"This product is the gold standard.","zh-TW":"這個產品是黃金標準。"},{"en":"Gold prices rose sharply.","zh-TW":"金價大幅上漲。"}]', '{"noun":"gold","adjective":"golden"}', NULL, 1, 962),
(963, 'goods', '/ɡʊdz/', 'noun', '{"zh-TW":["商品；貨物"],"en":["items for sale; merchandise"]}', NULL, 'consumer/manufactured goods', '[{"en":"The goods were shipped last week.","zh-TW":"貨物上週已發出。"},{"en":"Consumer goods make up 60% of our sales.","zh-TW":"消費品佔我們銷售額的60%。"}]', '{"noun":"goods"}', NULL, 2, 963),
(964, 'govern', '/ˈɡʌvərn/', 'verb', '{"zh-TW":["治理；管理","統治；管理"],"en":["to control and direct public affairs; to regulate","to officially control a country or organization"]}', NULL, 'govern by rules/laws; govern a country / governing body', '[{"en":"The country is governed by a democratic system.","zh-TW":"該國由民主制度治理。"},{"en":"Clear rules govern the use of company assets.","zh-TW":"明確的規則管理公司資產的使用。"},{"en":"The country is governed by a president.","zh-TW":"這個國家由總統統治。"},{"en":"Laws govern how businesses operate.","zh-TW":"法律規範企業的營運方式。"}]', '{"noun":"government/governance/governor","verb":"govern","noun2":"governor","noun3":"governance"}', NULL, 2, 964),
(965, 'grace', '/ɡreɪs/', 'noun', '{"zh-TW":["寬限；優雅"],"en":["a period of extra time; elegance"]}', NULL, 'grace period', '[{"en":"There is a 30-day grace period for payment.","zh-TW":"有30天的寬限期付款。"},{"en":"She handled the crisis with grace.","zh-TW":"她優雅地處理了危機。"}]', '{"noun":"grace","adjective":"graceful/gracious"}', NULL, 2, 965),
(966, 'grade', '/ɡreɪd/', 'noun / verb', '{"zh-TW":["等級；評分","成績；年級"],"en":["a level of quality; to assess performance","a mark showing how good work is"]}', NULL, 'high/top grade; get good grades / grade point average', '[{"en":"The product is available in different grades.","zh-TW":"產品有不同的等級。"},{"en":"Papers were graded by the instructor.","zh-TW":"報告由講師評分。"},{"en":"She always gets good grades.","zh-TW":"她總是拿好成績。"},{"en":"He''s in the fifth grade.","zh-TW":"他讀五年級。"}]', '{"noun":"grade/grading","verb":"grade","noun2":"grading"}', NULL, 2, 966),
