(970, 'grasp', '/ɡræsp/', 'verb / noun', '{"zh-TW":["掌握；理解"],"en":["to seize; to understand"]}', NULL, 'grasp a concept/opportunity', '[{"en":"She quickly grasped the concept.","zh-TW":"她很快掌握了這個概念。"},{"en":"Success is within our grasp.","zh-TW":"成功在我們的掌握之中。"}]', '{"noun":"grasp","verb":"grasp"}', NULL, 2, 970),
(971, 'grateful', '/ˈɡreɪtfəl/', 'adjective', '{"zh-TW":["感激的"],"en":["feeling thankful","feeling or showing thanks"]}', '{"root":{"text":"grat","meaning":"pleasing (令人愉悅)"},"suffix":{"text":"-ful","meaning":"full of (充滿)"},"logic":"充滿感謝之情的。"}', 'grateful for/to; grateful for / deeply grateful', '[{"en":"We are grateful for your continued support.","zh-TW":"我們感謝您持續的支持。"},{"en":"I would be grateful if you could reply promptly.","zh-TW":"如果您能及時回覆，我將不勝感激。"},{"en":"I''m grateful for your help.","zh-TW":"我很感激你的幫助。"},{"en":"She was deeply grateful to her mentor.","zh-TW":"她對她的導師深懷感激。"}]', '{"noun":"gratitude","adjective":"grateful","adverb":"gratefully"}', NULL, 3, 971),
(972, 'grave', '/ɡreɪv/', 'adjective', '{"zh-TW":["嚴重的；嚴肅的"],"en":["serious; giving cause for concern"]}', NULL, 'grave concern/consequences', '[{"en":"This is a matter of grave concern.","zh-TW":"這是一件令人嚴重關切的事。"},{"en":"The error could have grave consequences.","zh-TW":"這個錯誤可能有嚴重的後果。"}]', '{"noun":"gravity","adjective":"grave","adverb":"gravely"}', NULL, 2, 972),
(973, 'green', '/ɡriːn/', 'adjective', '{"zh-TW":["綠色的；環保的"],"en":["the color of grass","environmentally friendly"]}', NULL, 'go green / green energy', '[{"en":"Our company decided to go green.","zh-TW":"我們公司決定走環保路線。"},{"en":"We invest in green energy projects.","zh-TW":"我們投資綠色能源專案。"}]', '{"adjective":"green","noun":"green","noun2":"greenhouse"}', NULL, 2, 973),
