(976, 'grow', '/ɡroʊ/', 'verb', '{"zh-TW":["成長；增加"],"en":["to increase in size or number","to develop"]}', NULL, 'grow rapidly / grow a business', '[{"en":"The company has grown rapidly.","zh-TW":"公司快速成長。"},{"en":"We plan to grow our customer base.","zh-TW":"我們計畫擴大客戶群。"}]', '{"verb":"grow","noun":"growth","adjective":"growing"}', NULL, 1, 976),
(977, 'guarantee', '/ˌɡærənˈtiː/', 'noun / verb', '{"zh-TW":["保證；擔保"],"en":["a formal promise; to give a guarantee","a promise that something will be done or will happen"]}', '{"root":{"text":"garant","meaning":"warrant (擔保)"},"logic":"給予擔保的承諾。"}', 'money-back guarantee; money-back guarantee / under guarantee', '[{"en":"The product comes with a two-year guarantee.","zh-TW":"產品附有兩年保固。"},{"en":"We guarantee delivery within 48 hours.","zh-TW":"我們保證48小時內送達。"},{"en":"The product comes with a two-year guarantee.","zh-TW":"該產品附有兩年保固。"},{"en":"There is no guarantee of success.","zh-TW":"沒有成功的保證。"}]', '{"noun":"guarantee/guarantor","verb":"guarantee"}', NULL, 3, 977),
