(985, 'hail', '/heɪl/', 'noun', '{"zh-TW":["冰雹"],"en":["pellets of frozen rain falling from clouds"]}', '{"root":{"text":"hail","meaning":"hailstone (冰雹)"},"logic":"指從雲中落下的冰粒。"}', 'hailstorm / hail damage', '[{"en":"The hail damaged several cars in the parking lot.","zh-TW":"冰雹損壞了停車場的幾輛車。"},{"en":"A sudden hailstorm caught everyone off guard.","zh-TW":"突如其來的冰雹讓所有人措手不及。"}]', '{"noun":"hailstorm"}', NULL, 1, 985),
