(988, 'halt', '/hɔːlt/', 'verb, noun', '{"zh-TW":["停止；中止","暫停"],"en":["to stop or cause to stop","a temporary stop"]}', NULL, 'come to a halt / halt production', '[{"en":"The project was halted due to budget cuts.","zh-TW":"該項目因預算削減而停止。"},{"en":"Traffic came to a halt during the storm.","zh-TW":"暴風雨期間交通完全停止。"}]', '{"noun":"halt","verb":"halt"}', NULL, 1, 988),
(989, 'hamper', '/ˈhæmpər/', 'verb', '{"zh-TW":["妨礙；阻礙"],"en":["to prevent someone from easily doing something"]}', NULL, 'hamper progress/efforts/growth', '[{"en":"Bad weather hampered rescue efforts.","zh-TW":"惡劣天氣妨礙了救援工作。"},{"en":"Lack of funding hampered the research.","zh-TW":"缺乏資金阻礙了研究進展。"}]', '{"noun":"hamper","verb":"hamper"}', NULL, 2, 989),
