(994, 'harass', '/həˈræs/', 'verb', '{"zh-TW":["騷擾；煩擾"],"en":["to subject to aggressive pressure or intimidation"]}', NULL, 'harass someone / sexually harass', '[{"en":"Employees who harass others will face disciplinary action.","zh-TW":"騷擾他人的員工將面臨紀律處分。"},{"en":"She was harassed by persistent sales calls.","zh-TW":"她被持續不斷的推銷電話所騷擾。"}]', '{"noun":"harassment","verb":"harass"}', NULL, 2, 994),
