(1041, 'host', '/hoʊst/', 'noun, verb', '{"zh-TW":["主人；主辦方","主辦；招待"],"en":["a person who receives or entertains guests","to organize an event"]}', NULL, 'host a conference/event/party', '[{"en":"Tokyo will host the next international summit.","zh-TW":"東京將主辦下一屆國際峰會。"},{"en":"She was a gracious host at the dinner party.","zh-TW":"她在晚宴上是位優雅的女主人。"}]', '{"noun":"host, hostess","verb":"host"}', NULL, 1, 1041),
