(1043, 'hot', '/hɒt/', 'adjective', '{"zh-TW":["熱的；熱門的"],"en":["having high temperature","very popular"]}', NULL, 'hot topic / hot market', '[{"en":"AI is a hot topic right now.","zh-TW":"人工智慧現在是熱門話題。"},{"en":"The real estate market is very hot.","zh-TW":"房地產市場非常火熱。"}]', '{"adjective":"hot","noun":"heat","verb":"heat"}', NULL, 1, 1043),
(1044, 'hotel', '/hoʊˈtɛl/', 'noun', '{"zh-TW":["旅館；飯店"],"en":["a building providing accommodation for travelers"]}', NULL, 'hotel reservation / hotel chain', '[{"en":"I made a hotel reservation for the trip.","zh-TW":"我為出差預訂了飯店。"},{"en":"They manage a hotel chain.","zh-TW":"他們經營一家連鎖飯店。"}]', '{"noun":"hotel","noun2":"hotelier"}', NULL, 2, 1044),
(1045, 'hour', '/ˈaʊər/', 'noun', '{"zh-TW":["小時；時間"],"en":["a period of 60 minutes"]}', NULL, 'office hours / per hour', '[{"en":"Office hours are from 9 to 5.","zh-TW":"辦公時間是9點到5點。"},{"en":"The rate is $50 per hour.","zh-TW":"費率是每小時50美元。"}]', '{"noun":"hour","adjective":"hourly"}', NULL, 1, 1045),
(1046, 'house', '/haʊs/', 'noun', '{"zh-TW":["房子；公司"],"en":["a building for living in","a business firm"]}', NULL, 'in-house / publishing house', '[{"en":"We handle design in-house.","zh-TW":"我們內部處理設計。"},{"en":"She works for a publishing house.","zh-TW":"她在一家出版社工作。"}]', '{"noun":"house","noun2":"housing","verb":"house","noun3":"household"}', NULL, 2, 1046),
(1047, 'household', '/ˈhaʊshoʊld/', 'noun, adjective', '{"zh-TW":["家庭；住戶","家庭的；家用的"],"en":["all the people living together in a house","relating to a house or family"]}', NULL, 'household income/expenses/chores', '[{"en":"The average household income has risen this year.","zh-TW":"今年平均家庭收入有所上升。"},{"en":"She manages all the household expenses.","zh-TW":"她管理所有的家庭開支。"}]', '{"noun":"household, householder"}', NULL, 3, 1047),
(1048, 'housing', '/ˈhaʊzɪŋ/', 'noun', '{"zh-TW":["住房；住宅"],"en":["buildings for people to live in"]}', NULL, 'affordable housing / housing market / housing development', '[{"en":"The city needs more affordable housing.","zh-TW":"這座城市需要更多經濟適用房。"},{"en":"Housing prices have increased dramatically.","zh-TW":"房價大幅上漲。"}]', '{"noun":"housing, house","verb":"house"}', NULL, 3, 1048),
(1049, 'hub', '/hʌb/', 'noun', '{"zh-TW":["中心；樞紐"],"en":["the central and most important part of a network"]}', NULL, 'transportation/business/innovation hub', '[{"en":"Singapore is a major business hub in Asia.","zh-TW":"新加坡是亞洲主要的商業樞紐。"},{"en":"The city is becoming a tech innovation hub.","zh-TW":"這座城市正在成為科技創新中心。"}]', '{"noun":"hub"}', NULL, 1, 1049);
INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank) VALUES
(1050, 'human', '/ˈhjuːmən/', 'adjective', '{"zh-TW":["人的；人類的"],"en":["relating to people"]}', NULL, 'human resources / human rights', '[{"en":"Contact the human resources department.","zh-TW":"請聯繫人力資源部門。"},{"en":"We respect human rights in all operations.","zh-TW":"我們在所有營運中尊重人權。"}]', '{"adjective":"human","noun":"human","noun2":"humanity","noun3":"humanitarian"}', NULL, 2, 1050),
(1051, 'humanitarian', '/hjuːˌmænɪˈteriən/', 'adjective, noun', '{"zh-TW":["人道主義的","人道主義者"],"en":["concerned with reducing suffering","a person promoting human welfare"]}', NULL, 'humanitarian aid/crisis/organization', '[{"en":"The organization provides humanitarian aid to refugees.","zh-TW":"該組織為難民提供人道主義援助。"},{"en":"A humanitarian crisis is unfolding in the region.","zh-TW":"該地區正面臨人道主義危機。"}]', '{"noun":"humanitarian, humanity","adjective":"humanitarian, humane"}', NULL, 4, 1051),
(1052, 'humble', '/ˈhʌmbl/', 'adjective', '{"zh-TW":["謙虛的；卑微的"],"en":["having a modest view of one''s importance"]}', '{"root":{"text":"humil","meaning":"ground (地面)"},"logic":"源自拉丁語 humilis（低的），指不自視甚高。"}', 'humble beginnings / stay humble', '[{"en":"Despite his success, he remains humble.","zh-TW":"儘管成功，他仍然很謙虛。"},{"en":"She came from humble beginnings.","zh-TW":"她出身卑微。"}]', '{"noun":"humility","verb":"humble"}', NULL, 2, 1052),
(1053, 'humidity', '/hjuːˈmɪdəti/', 'noun', '{"zh-TW":["濕度"],"en":["the amount of water vapor in the air"]}', '{"root":{"text":"humid","meaning":"moist (潮濕)"},"suffix":{"text":"-ity","meaning":"state of (狀態)"},"logic":"潮濕的程度，即「濕度」。"}', 'high humidity / humidity level', '[{"en":"The humidity is very high in summer.","zh-TW":"夏天濕度很高。"},{"en":"High humidity makes it feel hotter.","zh-TW":"高濕度使體感更熱。"}]', '{"adjective":"humid","verb":"humidify","noun":"humidifier"}', NULL, 3, 1053),
(1054, 'hungry', '/ˈhʌŋɡri/', 'adjective', '{"zh-TW":["飢餓的；渴望的"],"en":["wanting food","eager for something"]}', NULL, 'power hungry / hungry for success', '[{"en":"The team is hungry for success.","zh-TW":"團隊渴望成功。"},{"en":"Shall we order lunch? I am hungry.","zh-TW":"我們點午餐吧？我餓了。"}]', '{"adjective":"hungry","noun":"hunger","adverb":"hungrily"}', NULL, 2, 1054),
(1055, 'hurdle', '/ˈhɜːrdl/', 'noun', '{"zh-TW":["障礙；難關"],"en":["a difficulty or obstacle to overcome"]}', NULL, 'overcome/clear a hurdle / regulatory hurdle', '[{"en":"The new regulation is a major hurdle for startups.","zh-TW":"新法規是新創公司的一大障礙。"},{"en":"We still have several hurdles to clear before launch.","zh-TW":"在推出之前我們還有幾個障礙需要克服。"}]', '{"noun":"hurdle","verb":"hurdle"}', NULL, 2, 1055),
(1056, 'hurricane', '/ˈhɜːrɪkeɪn/', 'noun', '{"zh-TW":["颶風"],"en":["a violent tropical storm with very strong winds"]}', '{"root":{"text":"hurricane","meaning":"god of storm (風暴之神)"},"logic":"源自加勒比原住民語言 hurakán（風暴之神）。"}', 'hurricane season / hurricane warning', '[{"en":"The hurricane caused billions of dollars in damage.","zh-TW":"颶風造成數十億美元的損害。"},{"en":"Residents evacuated before the hurricane hit.","zh-TW":"居民在颶風來襲前撤離。"}]', NULL, NULL, 3, 1056),
(1057, 'hurry', '/ˈhʌri/', 'verb', '{"zh-TW":["趕快；匆忙"],"en":["to move or do something quickly"]}', NULL, 'in a hurry / hurry up', '[{"en":"I am in a hurry to catch my flight.","zh-TW":"我趕著搭飛機。"},{"en":"We need to hurry to meet the deadline.","zh-TW":"我們得趕快以趕上截止日期。"}]', '{"verb":"hurry","noun":"hurry","adjective":"hurried","adverb":"hurriedly"}', NULL, 2, 1057),
(1058, 'husband', '/ˈhʌzbənd/', 'noun', '{"zh-TW":["【主要意義-名詞】丈夫","【次要意義-動詞】節約使用；精打細算地管理（資源）"],"en":["[primary - noun] a married man","[secondary - verb] to use something carefully and economically; to conserve resources"]}', NULL, 'husband resources / husband one''s strength / husband energy', '[{"en":"The company must husband its resources carefully during the economic downturn.","zh-TW":"在經濟衰退期間，公司必須謹慎地節約使用資源。"},{"en":"She husbanded her energy for the final push of the marathon.","zh-TW":"她節省體力以備馬拉松最後衝刺之用。"},{"en":"Good farmers husband the land to ensure long-term productivity.","zh-TW":"好的農夫會善加管理土地以確保長期生產力。"}]', '{"noun":"husbandry"}', '動詞 husband 與名詞「丈夫」毫無關聯，意為「節儉管理資源」，常見於 TOEIC 描述資源管理或商業策略的閱讀題。', 3, 1058),
(1059, 'hygiene', '/ˈhaɪdʒiːn/', 'noun', '{"zh-TW":["衛生"],"en":["conditions or practices conducive to maintaining health"]}', NULL, 'personal/food hygiene', '[{"en":"Good hygiene is essential in food preparation.","zh-TW":"良好的衛生對食品製備至關重要。"},{"en":"The restaurant was closed due to poor hygiene.","zh-TW":"這家餐廳因衛生不合格而關閉。"}]', '{"noun":"hygiene","adjective":"hygienic"}', NULL, 3, 1059),
(1060, 'hype', '/haɪp/', 'noun, verb', '{"zh-TW":["炒作；大肆宣傳"],"en":["excessive publicity or promotion"]}', NULL, 'media hype / live up to the hype / hype up', '[{"en":"The product failed to live up to the hype.","zh-TW":"該產品未能達到宣傳的效果。"},{"en":"The media hyped the event for weeks.","zh-TW":"媒體連續幾週大肆炒作這個活動。"}]', '{"noun":"hype","verb":"hype","adjective":"hyped"}', NULL, 1, 1060),
(1061, 'hypothesis', '/haɪˈpɑːθəsɪs/', 'noun', '{"zh-TW":["假設；假說"],"en":["a proposed explanation made as a starting point for investigation"]}', NULL, 'test/support/reject a hypothesis', '[{"en":"The scientist tested her hypothesis through experiments.","zh-TW":"這位科學家通過實驗驗證了她的假說。"},{"en":"Our hypothesis proved to be correct.","zh-TW":"我們的假設被證明是正確的。"}]', '{"noun":"hypothesis","adjective":"hypothetical","verb":"hypothesize"}', NULL, 4, 1061),
(1062, 'hypothesize', '/haɪˈpɑːθəsaɪz/', 'verb', '{"zh-TW":["假設；假定"],"en":["to form a hypothesis"]}', NULL, 'hypothesize that / hypothesize about', '[{"en":"Researchers hypothesized that the treatment would reduce symptoms.","zh-TW":"研究人員假設這種治療會減輕症狀。"},{"en":"We can hypothesize about possible outcomes.","zh-TW":"我們可以對可能的結果進行假設。"}]', '{"noun":"hypothesis","verb":"hypothesize","adjective":"hypothetical"}', NULL, 4, 1062),
(1063, 'hypothetical', '/ˌhaɪpəˈθetɪkl/', 'adjective', '{"zh-TW":["假設的；假定的"],"en":["based on an assumption rather than fact"]}', NULL, 'hypothetical situation/scenario/question', '[{"en":"Let me give you a hypothetical scenario.","zh-TW":"讓我給你一個假設的情境。"},{"en":"This is purely hypothetical at this stage.","zh-TW":"在現階段這純粹是假設性的。"}]', '{"noun":"hypothesis","adjective":"hypothetical","verb":"hypothesize"}', NULL, 4, 1063),
(1064, 'ice', '/aɪs/', 'noun', '{"zh-TW":["冰"],"en":["frozen water"]}', NULL, 'break the ice / on ice', '[{"en":"Let me break the ice with a quick introduction.","zh-TW":"讓我先自我介紹來打破僵局。"},{"en":"The plan is on ice for now.","zh-TW":"這個計畫暫時被擱置了。"}]', '{"noun":"ice","adjective":"icy","verb":"ice"}', NULL, 1, 1064),
(1065, 'icon', '/ˈaɪkɑːn/', 'noun', '{"zh-TW":["圖標；偶像"],"en":["a symbol on a computer screen; a famous person"]}', NULL, 'click the icon / fashion icon / cultural icon', '[{"en":"Click the icon to open the application.","zh-TW":"點擊圖標打開應用程序。"},{"en":"Steve Jobs was a tech industry icon.","zh-TW":"史蒂夫·賈伯斯是科技產業的偶像。"}]', '{"noun":"icon","adjective":"iconic"}', NULL, 1, 1065),
(1066, 'idea', '/aɪˈdɪə/', 'noun', '{"zh-TW":["想法；主意"],"en":["a thought or suggestion"]}', NULL, 'good idea / no idea', '[{"en":"That is a great idea for the campaign.","zh-TW":"那是一個很棒的活動點子。"},{"en":"I have no idea why it failed.","zh-TW":"我不知道為什麼失敗了。"}]', '{"noun":"idea","adjective":"ideal","adverb":"ideally","noun2":"idealism"}', NULL, 1, 1066),
(1067, 'ideal', '/aɪˈdiːəl/', 'adjective, noun', '{"zh-TW":["理想的","理想"],"en":["most suitable; perfect","a standard of perfection"]}', NULL, 'ideal candidate/solution/location', '[{"en":"She is the ideal candidate for this position.","zh-TW":"她是這個職位的理想人選。"},{"en":"This location is ideal for our new office.","zh-TW":"這個地點是我們新辦公室的理想選擇。"}]', '{"noun":"ideal, idealism","adjective":"ideal","adverb":"ideally"}', NULL, 2, 1067),
(1068, 'identify', '/aɪˈdentɪfaɪ/', 'verb', '{"zh-TW":["識別；辨認","確認"],"en":["to establish the identity of","to recognize or establish the identity of","to determine"]}', '{"root":{"text":"ident","meaning":"same (相同)"},"suffix":{"text":"-ify","meaning":"make (使)"},"logic":"使確認為同一個，即「識別」。"}', 'identify a problem / identify with / identify the cause; identify a problem/need/trend', '[{"en":"Can you identify the person in this photo?","zh-TW":"你能認出照片中的人嗎？"},{"en":"We need to identify the root cause.","zh-TW":"我們需要找出根本原因。"},{"en":"The police identified the suspect from CCTV footage.","zh-TW":"警方從監控錄像中辨認出了嫌疑人。"},{"en":"We need to identify the root cause of the issue.","zh-TW":"我們需要找出問題的根本原因。"}]', '{"noun":"identification","noun2":"identity","adjective":"identifiable","verb":"identify"}', NULL, 3, 1068),
(1069, 'ignore', '/ɪɡˈnɔːr/', 'verb', '{"zh-TW":["忽視；不理睬"],"en":["to refuse to take notice of"]}', NULL, 'ignore advice/warnings/rules', '[{"en":"You should not ignore the safety warnings.","zh-TW":"你不應該忽視安全警告。"},{"en":"He chose to ignore her complaints.","zh-TW":"他選擇忽視她的投訴。"}]', '{"noun":"ignorance","verb":"ignore","adjective":"ignorant"}', NULL, 2, 1069),
(1070, 'illustrate', '/ˈɪləstreɪt/', 'verb', '{"zh-TW":["說明；描繪","說明；闡釋","為...加插圖"],"en":["to explain or make clear by using examples or pictures","to explain by examples","to provide pictures for a book"]}', '{"prefix":{"text":"il-","meaning":"in (在內)"},"root":{"text":"lustr","meaning":"light (光)"},"suffix":{"text":"-ate","meaning":"make (使)"},"logic":"使光照入使其清楚，即「說明」。"}', 'illustrate a point / clearly illustrate; illustrate a point/concept', '[{"en":"The graph illustrates the trend clearly.","zh-TW":"圖表清楚地說明了趨勢。"},{"en":"Let me illustrate with an example.","zh-TW":"讓我用一個例子來說明。"},{"en":"The chart illustrates the trend in sales.","zh-TW":"這張圖表說明了銷售趨勢。"},{"en":"Let me illustrate my point with an example.","zh-TW":"讓我用一個例子來說明我的觀點。"}]', '{"noun":"illustration","noun2":"illustrator","verb":"illustrate","adjective":"illustrative"}', NULL, 4, 1070),
(1071, 'image', '/ˈɪmɪdʒ/', 'noun', '{"zh-TW":["形象；圖像"],"en":["the impression people have of a person or company; a picture"]}', NULL, 'brand/public/corporate image', '[{"en":"The company is trying to improve its public image.","zh-TW":"公司正在努力改善其公眾形象。"},{"en":"Digital images can be edited easily.","zh-TW":"數位圖像可以輕鬆編輯。"}]', '{"noun":"image, imagery","verb":"imagine","adjective":"imaginary"}', NULL, 2, 1071),
(1072, 'imagine', '/ɪˈmædʒɪn/', 'verb', '{"zh-TW":["想像"],"en":["to form a mental picture of something"]}', NULL, 'hard to imagine / imagine that', '[{"en":"Imagine how the customer feels.","zh-TW":"想像客戶的感受。"},{"en":"It is hard to imagine life without technology.","zh-TW":"很難想像沒有科技的生活。"}]', '{"verb":"imagine","noun":"imagination","adjective":"imaginative","adjective2":"imaginary"}', NULL, 3, 1072),
(1073, 'immediate', '/ɪˈmiːdiət/', 'adjective', '{"zh-TW":["立即的；即時的","直接的"],"en":["happening without delay","nearest in time or relationship"]}', NULL, 'immediate action/response/effect', '[{"en":"We need to take immediate action on this matter.","zh-TW":"我們需要對此事立即採取行動。"},{"en":"The immediate effect was a rise in stock prices.","zh-TW":"直接效果是股價上漲。"}]', '{"noun":"immediacy","adjective":"immediate","adverb":"immediately"}', NULL, 3, 1073),
(1074, 'immense', '/ɪˈmens/', 'adjective', '{"zh-TW":["巨大的；龐大的"],"en":["extremely large or great"]}', NULL, 'immense pressure/value/potential', '[{"en":"The project requires an immense amount of resources.","zh-TW":"該項目需要大量資源。"},{"en":"She has immense experience in the field.","zh-TW":"她在該領域有豐富的經驗。"}]', '{"noun":"immensity","adjective":"immense","adverb":"immensely"}', NULL, 3, 1074),
(1075, 'immune', '/ɪˈmjuːn/', 'adjective', '{"zh-TW":["免疫的；不受影響的"],"en":["resistant to; not affected by"]}', NULL, 'immune to / immune system / immune from', '[{"en":"No company is immune to economic downturns.","zh-TW":"沒有公司能免受經濟衰退的影響。"},{"en":"The new policy makes no one immune from accountability.","zh-TW":"新政策使沒有人能免除問責。"}]', '{"noun":"immunity, immunization","adjective":"immune","verb":"immunize"}', NULL, 2, 1075),
(1076, 'impact', '/ˈɪmpækt/', 'noun, verb', '{"zh-TW":["影響；衝擊"],"en":["a strong effect or influence"]}', NULL, 'have an impact on / environmental impact', '[{"en":"The new policy will have a significant impact on small businesses.","zh-TW":"新政策將對小企業產生重大影響。"},{"en":"Climate change impacts everyone.","zh-TW":"氣候變遷影響每個人。"}]', '{"noun":"impact","verb":"impact","adjective":"impactful"}', NULL, 2, 1076),
(1077, 'impair', '/ɪmˈper/', 'verb', '{"zh-TW":["損害；削弱"],"en":["to weaken or damage something"]}', NULL, 'impair vision/judgment/performance', '[{"en":"Alcohol can impair your judgment.","zh-TW":"酒精會損害你的判斷力。"},{"en":"Noise pollution can impair hearing over time.","zh-TW":"噪音污染長期下來會損害聽力。"}]', '{"noun":"impairment","verb":"impair","adjective":"impaired"}', NULL, 2, 1077),
(1078, 'impatient', '/ɪmˈpeɪʃnt/', 'adjective', '{"zh-TW":["不耐煩的"],"en":["not willing to wait or unable to tolerate delay"]}', '{"prefix":{"text":"im-","meaning":"not (不)"},"root":{"text":"patient","meaning":"enduring (忍耐)"},"logic":"不能忍耐的，即「不耐煩的」。"}', 'grow impatient / impatient with', '[{"en":"He grew impatient waiting for the bus.","zh-TW":"他等公車等得不耐煩了。"},{"en":"Don''t be so impatient with the children.","zh-TW":"對孩子們不要那麼沒耐心。"}]', '{"noun":"impatience","adverb":"impatiently"}', NULL, 3, 1078),
(1079, 'impeach', '/ɪmˈpiːtʃ/', 'verb', '{"zh-TW":["彈劾"],"en":["to charge a public official with misconduct"]}', NULL, 'impeach a president / impeachment trial', '[{"en":"Congress voted to impeach the president.","zh-TW":"國會投票彈劾總統。"},{"en":"The impeachment process began.","zh-TW":"彈劾程序開始了。"}]', '{"noun":"impeachment"}', NULL, 3, 1079),
(1080, 'impede', '/ɪmˈpiːd/', 'verb', '{"zh-TW":["妨礙；阻礙"],"en":["to delay or prevent something"]}', NULL, 'impede progress/growth/development', '[{"en":"Bureaucracy can impede the progress of reforms.","zh-TW":"官僚主義會妨礙改革的進展。"},{"en":"The construction work impeded traffic flow.","zh-TW":"施工妨礙了交通流暢。"}]', '{"noun":"impediment","verb":"impede"}', NULL, 2, 1080),
(1081, 'imperative', '/ɪmˈperətɪv/', 'adjective, noun', '{"zh-TW":["迫切的；必要的","必要的事"],"en":["extremely important and urgent","something vital"]}', NULL, 'it is imperative that / moral imperative', '[{"en":"It is imperative that we act quickly.","zh-TW":"我們迫切需要迅速行動。"},{"en":"Data security is a business imperative.","zh-TW":"數據安全是商業上的當務之急。"}]', '{"noun":"imperative","adjective":"imperative"}', NULL, 4, 1081),
(1082, 'implement', '/ˈɪmplɪment/', 'verb', '{"zh-TW":["實施；執行","工具；器具"],"en":["to put into effect","to put a plan into action","a tool or instrument"]}', '{"prefix":{"text":"im-","meaning":"in (進入)"},"root":{"text":"ple","meaning":"fill (充滿)"},"suffix":{"text":"-ment","meaning":"result (結果)"},"logic":"充實到行動中，即「實施」。"}', 'implement a plan / implement changes / implement a policy; implement a plan/policy/strategy', '[{"en":"The company will implement the new policy next month.","zh-TW":"公司下個月將實施新政策。"},{"en":"It takes time to implement changes.","zh-TW":"實施變革需要時間。"},{"en":"The government plans to implement new regulations.","zh-TW":"政府計劃實施新的法規。"},{"en":"The changes will be implemented next quarter.","zh-TW":"這些變更將在下個季度實施。"}]', '{"noun":"implementation","verb":"implement"}', NULL, 3, 1082),
(1083, 'implication', '/ˌɪmplɪˈkeɪʃn/', 'noun', '{"zh-TW":["含義；暗示","影響；後果"],"en":["something suggested without being stated","a possible consequence"]}', NULL, 'have implications for / the implications of', '[{"en":"The findings have serious implications for public health.","zh-TW":"這些發現對公共衛生有嚴重影響。"},{"en":"What are the implications of this decision?","zh-TW":"這個決定有什麼含義？"}]', '{"noun":"implication","verb":"imply, implicate","adjective":"implicit"}', NULL, 4, 1083),
(1084, 'implicit', '/ɪmˈplɪsɪt/', 'adjective', '{"zh-TW":["含蓄的；隱含的"],"en":["implied though not directly expressed"]}', NULL, 'implicit assumption/understanding/trust', '[{"en":"There was an implicit understanding between the partners.","zh-TW":"合作夥伴之間有一種默契。"},{"en":"The risks are implicit in the contract terms.","zh-TW":"風險隱含在合同條款中。"}]', '{"adjective":"implicit","adverb":"implicitly","noun":"implication"}', NULL, 3, 1084),
(1085, 'imply', '/ɪmˈplaɪ/', 'verb', '{"zh-TW":["暗示；意味著"],"en":["to suggest without stating directly","to suggest something without saying it directly"]}', '{"prefix":{"text":"im-","meaning":"in (在內)"},"root":{"text":"ply","meaning":"fold (折疊)"},"logic":"把意思折藏在裡面，即「暗示」。"}', 'imply that / strongly imply', '[{"en":"Are you implying that I''m wrong?","zh-TW":"你是在暗示我錯了嗎？"},{"en":"The data implies a connection between the two variables.","zh-TW":"數據暗示兩個變數之間有關聯。"},{"en":"Are you implying that I made a mistake?","zh-TW":"你是在暗示我犯了錯嗎？"},{"en":"The data implies a strong correlation.","zh-TW":"數據暗示了很強的相關性。"}]', '{"noun":"implication","adjective":"implicit","verb":"imply"}', NULL, 2, 1085),
(1086, 'import', '/ˈɪmpɔːrt/', 'noun, verb', '{"zh-TW":["進口；輸入","進口商品"],"en":["to bring goods from another country","goods brought from abroad"]}', NULL, 'import goods/products / import duties', '[{"en":"The country imports most of its oil.","zh-TW":"該國大部分石油依賴進口。"},{"en":"Import duties have been raised by 5%.","zh-TW":"進口關稅提高了5%。"}]', '{"noun":"import, importation, importer","verb":"import"}', NULL, 2, 1086),
(1087, 'important', '/ɪmˈpɔːrtənt/', 'adjective', '{"zh-TW":["重要的"],"en":["having great value or significance"]}', NULL, 'most important / important role', '[{"en":"Communication is the most important skill.","zh-TW":"溝通是最重要的技能。"},{"en":"She plays an important role in the project.","zh-TW":"她在專案中扮演重要角色。"}]', '{"adjective":"important","noun":"importance","adverb":"importantly","adjective2":"unimportant"}', NULL, 3, 1087),
(1088, 'impose', '/ɪmˈpoʊz/', 'verb', '{"zh-TW":["施加；強加","強加；施加","徵收"],"en":["to force something on someone","to establish a tax or fine"]}', '{"prefix":{"text":"im-","meaning":"on (在上)"},"root":{"text":"pose","meaning":"put (放置)"},"logic":"把東西放在某人身上，即「強加」。"}', 'impose restrictions / impose a fine / impose on; impose restrictions/sanctions/a fine', '[{"en":"The government imposed new taxes on imports.","zh-TW":"政府對進口商品徵收新稅。"},{"en":"I don''t want to impose on your time.","zh-TW":"我不想占用你的時間。"},{"en":"The government imposed new restrictions on imports.","zh-TW":"政府對進口實施了新的限制。"},{"en":"A heavy fine was imposed on the company.","zh-TW":"公司被處以高額罰款。"}]', '{"noun":"imposition","verb":"impose"}', NULL, 2, 1088),
(1089, 'impress', '/ɪmˈpres/', 'verb', '{"zh-TW":["使印象深刻；使欽佩"],"en":["to make someone feel admiration"]}', NULL, 'impress someone with / be impressed by', '[{"en":"Her presentation impressed the entire board.","zh-TW":"她的報告讓整個董事會印象深刻。"},{"en":"I was very impressed by the quality of the work.","zh-TW":"我對工作的品質印象非常深刻。"}]', '{"noun":"impression","verb":"impress","adjective":"impressive, impressed"}', NULL, 3, 1089),
(1090, 'improve', '/ɪmˈpruːv/', 'verb', '{"zh-TW":["改善；提高"],"en":["to make or become better"]}', NULL, 'improve performance/quality/efficiency', '[{"en":"The company needs to improve customer service.","zh-TW":"公司需要改善客戶服務。"},{"en":"His English has improved significantly.","zh-TW":"他的英語有了顯著的進步。"}]', '{"noun":"improvement","verb":"improve","adjective":"improved"}', NULL, 3, 1090),
(1091, 'impulse', '/ˈɪmpʌls/', 'noun', '{"zh-TW":["衝動；推動力"],"en":["a sudden strong urge; a driving force"]}', NULL, 'impulse buying / on impulse / impulse purchase', '[{"en":"Impulse buying accounts for 30% of retail sales.","zh-TW":"衝動購買佔零售銷售額的30%。"},{"en":"She bought the dress on impulse.","zh-TW":"她一時衝動買了那件洋裝。"}]', '{"noun":"impulse","adjective":"impulsive","adverb":"impulsively"}', NULL, 3, 1091),
(1092, 'inadequate', '/ɪnˈædɪkwət/', 'adjective', '{"zh-TW":["不足的；不充分的"],"en":["not enough or not good enough"]}', NULL, 'inadequate funding/resources/training', '[{"en":"The budget is inadequate for the project''s needs.","zh-TW":"預算不足以滿足項目需求。"},{"en":"Inadequate training led to the error.","zh-TW":"培訓不足導致了錯誤。"}]', '{"noun":"inadequacy","adjective":"inadequate","adverb":"inadequately"}', NULL, 4, 1092),
(1093, 'incentive', '/ɪnˈsentɪv/', 'noun', '{"zh-TW":["激勵；獎勵；動機"],"en":["something that encourages a person to do something"]}', NULL, 'financial/tax incentive / provide an incentive', '[{"en":"The company offers incentives to attract new employees.","zh-TW":"公司提供激勵措施來吸引新員工。"},{"en":"Tax incentives encourage business investment.","zh-TW":"稅收優惠鼓勵企業投資。"}]', '{"noun":"incentive","verb":"incentivize"}', NULL, 3, 1093),
(1094, 'incentivize', '/ɪnˈsentɪvaɪz/', 'verb', '{"zh-TW":["激勵；提供獎勵"],"en":["to provide incentives to encourage action"]}', NULL, 'incentivize employees/performance', '[{"en":"The program incentivizes employees to meet targets.","zh-TW":"該計劃激勵員工達成目標。"},{"en":"Tax breaks incentivize green energy investment.","zh-TW":"稅收優惠激勵綠色能源投資。"}]', '{"noun":"incentive","verb":"incentivize"}', NULL, 4, 1094),
(1095, 'incidence', '/ˈɪnsɪdəns/', 'noun', '{"zh-TW":["發生率"],"en":["the rate at which something occurs"]}', NULL, 'high/low incidence of', '[{"en":"There is a high incidence of diabetes in this region.","zh-TW":"該地區糖尿病發生率很高。"},{"en":"The incidence of workplace injuries has decreased.","zh-TW":"工傷事故發生率已經下降。"}]', '{"noun":"incidence, incident","adjective":"incidental"}', NULL, 3, 1095),
(1096, 'incident', '/ˈɪnsɪdənt/', 'noun', '{"zh-TW":["事件；事故"],"en":["an event, especially one that is unusual or unpleasant"]}', NULL, 'report an incident / security incident', '[{"en":"The incident was reported to the police.","zh-TW":"該事件已報告給警方。"},{"en":"Several minor incidents occurred during the event.","zh-TW":"活動期間發生了幾起小事故。"}]', '{"noun":"incident, incidence","adjective":"incidental","adverb":"incidentally"}', NULL, 3, 1096),
