(1098, 'include', '/ɪnˈkluːd/', 'verb', '{"zh-TW":["包括；包含"],"en":["to contain as part of a whole"]}', NULL, 'include information/details', '[{"en":"The price includes tax and delivery.","zh-TW":"價格包括稅金和運費。"},{"en":"Please include your contact details in the application.","zh-TW":"請在申請中包含您的聯繫方式。"}]', '{"noun":"inclusion","verb":"include","adjective":"inclusive, included"}', NULL, 3, 1098),
(1099, 'income', '/ˈɪnkʌm/', 'noun', '{"zh-TW":["收入；所得"],"en":["money received from work or investments"]}', NULL, 'annual/monthly income / income tax', '[{"en":"Her annual income exceeds $80,000.","zh-TW":"她的年收入超過8萬美元。"},{"en":"Income tax rates vary by bracket.","zh-TW":"所得稅稅率因級距而異。"}]', '{"noun":"income"}', NULL, 2, 1099);